  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.JS)
  const edits = [] // {start, end, text}
  const q = (s) => `'${s}'`

  for (const stmt of sf.statements) {
    // ---- requires
    if (ts.isVariableStatement(stmt) && stmt.declarationList.declarations.length === 1) {
      const decl = stmt.declarationList.declarations[0]
      const init = decl.initializer
      if (isRequireCall(init)) {
        const mod = init.arguments[0].text
        let replacement = null
        if (ts.isIdentifier(decl.name)) {
          replacement = `import ${decl.name.text} = require(${q(mod)})`
        } else if (ts.isObjectBindingPattern(decl.name) && decl.name.elements.every((e) => !e.initializer && !e.dotDotDotToken && ts.isIdentifier(e.name) && (!e.propertyName || ts.isIdentifier(e.propertyName)))) {
          const specs = decl.name.elements.map((e) => (e.propertyName ? `${e.propertyName.text} as ${e.name.text}` : e.name.text))
          replacement = `import { ${specs.join(', ')} } from ${q(mod)}`
        }
        if (replacement) {
          edits.push({ start: stmt.getStart(sf), end: stmt.getEnd(), text: replacement })
          continue
        } else {
          report.unhandledRequire.push(`${file}:${sf.getLineAndCharacterOfPosition(stmt.getStart(sf)).line + 1}`)
        }
      }
    }
    // ---- exports
    if (ts.isExpressionStatement(stmt) && ts.isBinaryExpression(stmt.expression) && stmt.expression.operatorToken.kind === ts.SyntaxKind.EqualsToken) {
      const { left, right } = stmt.expression
      if (isModuleExports(left)) {
        if (ts.isObjectLiteralExpression(right) && right.properties.every((p) => ts.isShorthandPropertyAssignment(p) || (ts.isPropertyAssignment(p) && ts.isIdentifier(p.name) && ts.isIdentifier(p.initializer)))) {
          const specs = right.properties.map((p) => (ts.isShorthandPropertyAssignment(p) ? p.name.text : p.initializer.text === p.name.text ? p.name.text : `${p.initializer.text} as ${p.name.text}`))
          edits.push({ start: stmt.getStart(sf), end: stmt.getEnd(), text: `export { ${specs.join(', ')} }` })
        } else {
          edits.push({ start: left.getStart(sf), end: right.getStart(sf), text: 'export = ' })
        }
        continue
      }
      if (ts.isPropertyAccessExpression(left) && isModuleExports(left.expression)) {
        const name = left.name.text
        if (ts.isIdentifier(right) && right.text === name) {
          edits.push({ start: stmt.getStart(sf), end: stmt.getEnd(), text: `export { ${name} }` })
        } else if (ts.isIdentifier(right)) {
          edits.push({ start: stmt.getStart(sf), end: stmt.getEnd(), text: `export { ${right.text} as ${name} }` })
        } else {
          edits.push({ start: left.getStart(sf), end: right.getStart(sf), text: `export const ${name} = ` })
        }
        continue
      }
    }
  }

  // ---- class constructor fields
  function visit(node) {
    if ((ts.isClassDeclaration(node) || ts.isClassExpression(node)) && node.members) {
      handleClass(node)
    }
    ts.forEachChild(node, visit)
  }
  function handleClass(cls) {
    const heritage = cls.heritageClauses?.find((h) => h.token === ts.SyntaxKind.ExtendsKeyword)
    const baseName = heritage ? heritage.types[0].expression.getText(sf) : null
    const isModel = baseName === 'Model'
    const ctor = cls.members.find(ts.isConstructorDeclaration)
    if (!ctor || !ctor.body) return
    const existing = new Set(cls.members.filter((m) => m.name && ts.isIdentifier(m.name)).map((m) => m.name.text))
    const fields = []
    const seen = new Set()
    for (const s of ctor.body.statements) {
      if (!ts.isExpressionStatement(s)) continue
      const e = s.expression
      const jsdocs = ts.getJSDocCommentsAndTags(s).filter(ts.isJSDoc)
      const jsdoc = jsdocs[jsdocs.length - 1]
      const typeTag = jsdoc?.tags?.find(ts.isJSDocTypeTag)
      const fullStart = s.getFullStart()
      // bare `this.x`
      if (ts.isPropertyAccessExpression(e) && e.expression.kind === ts.SyntaxKind.ThisKeyword) {
        const name = e.name.text
        if (seen.has(name) || existing.has(name)) continue
        seen.add(name)
        const comment = jsdoc ? jsdoc.getText(sf) : null
        fields.push({ name, comment, declare: true })
        // remove statement including its leading trivia (comments) up to previous line
        const start = lineStart(text, s.getStart(sf) - (s.getStart(sf) - (jsdoc ? jsdoc.getStart(sf) : s.getStart(sf))))
        let end = s.getEnd()
        if (text[end] === '\n') end++
        edits.push({ start, end, text: '' })
        // remove any non-jsdoc single-line comments directly above? leave them.
        void fullStart
        continue
      }
      // `this.x = value` with a JSDoc @type
      if (typeTag && ts.isBinaryExpression(e) && e.operatorToken.kind === ts.SyntaxKind.EqualsToken && ts.isPropertyAccessExpression(e.left) && e.left.expression.kind === ts.SyntaxKind.ThisKeyword) {
        const name = e.left.name.text
        if (seen.has(name) || existing.has(name)) continue
        seen.add(name)
        fields.push({ name, comment: jsdoc.getText(sf), declare: isModel || !!heritage })
        const start = lineStart(text, jsdoc.getStart(sf))
        const end = lineStart(text, s.getStart(sf))
        edits.push({ start, end, text: '' })
      }
    }
    if (!fields.length) return
    const indent = '  '
    const fieldText = fields
      .map((f) => {
        const c = f.comment ? f.comment.split('\n').map((l, i) => (i === 0 ? indent + l : indent + l.trimStart().replace(/^\*/, ' *'))).join('\n') + '\n' : ''
        return `${c}${indent}${f.declare ? 'declare ' : ''}${f.name}`
      })
      .join('\n')
    const insertAt = lineStart(text, ctor.getStart(sf) - (ctor.getStart(sf) - (ts.getJSDocCommentsAndTags(ctor)[0]?.getStart(sf) ?? ctor.getStart(sf))))
    edits.push({ start: insertAt, end: insertAt, text: fieldText + '\n\n' })
  }
  visit(sf)

  edits.sort((a, b) => b.start - a.start || b.end - a.end)
  for (const e of edits) text = text.slice(0, e.start) + e.text + text.slice(e.end)
  // JSDoc-only pseudo types used in this codebase
  text = text.replace(/\{UUIDV4\}/g, '{string}')
  fs.writeFileSync(file, text)
}

