// Usage: node lsfix.js <code,code,...> [mode]   mode: 'suggestion' (default) | 'semantic'
const ts = require('/home/danny/Code/compx574/audiobookshelf/node_modules/typescript')
const fs = require('fs')
const path = require('path')
const root = '/home/danny/Code/compx574/audiobookshelf'
const codes = process.argv[2].split(',').map(Number)
const mode = process.argv[3] || 'suggestion'

const cfgPath = path.join(root, 'tsconfig.server.json')
const cfg = ts.parseJsonConfigFileContent(ts.readConfigFile(cfgPath, ts.sys.readFile).config, ts.sys, root)
const files = new Map()
for (const f of cfg.fileNames) files.set(f, { text: fs.readFileSync(f, 'utf8'), version: 0 })
const host = {
  getScriptFileNames: () => [...files.keys()],
  getScriptVersion: (f) => String(files.get(f)?.version ?? 0),
  getScriptSnapshot: (f) => {
    const e = files.get(f)
    if (e) return ts.ScriptSnapshot.fromString(e.text)
    if (!fs.existsSync(f)) return undefined
    return ts.ScriptSnapshot.fromString(fs.readFileSync(f, 'utf8'))
  },
  getCurrentDirectory: () => root,
  getCompilationSettings: () => cfg.options,
  getDefaultLibFileName: (o) => ts.getDefaultLibFilePath(o),
  fileExists: ts.sys.fileExists,
  readFile: ts.sys.readFile,
  readDirectory: ts.sys.readDirectory,
  directoryExists: ts.sys.directoryExists,
  getDirectories: ts.sys.getDirectories
}
const ls = ts.createLanguageService(host, ts.createDocumentRegistry())
const fmt = ts.getDefaultFormatCodeSettings()
fmt.indentSize = 2
fmt.tabSize = 2
fmt.convertTabsToSpaces = true
fmt.semicolons = ts.SemicolonPreference.Remove
const prefs = { quotePreference: 'single', includeCompletionsForModuleExports: false }

function applyChanges(changes) {
  for (const c of changes) {
    const e = files.get(c.fileName)
    if (!e) continue
    const sorted = [...c.textChanges].sort((a, b) => b.span.start - a.span.start)
    let t = e.text
    for (const tc of sorted) t = t.slice(0, tc.span.start) + tc.newText + t.slice(tc.span.start + tc.span.length)
    e.text = t
    e.version++
    e.dirty = true
  }
}

const targets = [...files.keys()].filter((f) => f.endsWith('.ts') && !f.endsWith('.d.ts') && !f.includes('/libs/'))
let total = 0
for (let pass = 0; pass < 4; pass++) {
  let changedThisPass = 0
  for (const f of targets) {
    for (const code of codes) {
      const diags = (mode === 'semantic' ? ls.getSemanticDiagnostics(f) : ls.getSuggestionDiagnostics(f)).filter((d) => d.code === code)
      if (!diags.length) continue
      let fixId = null
      for (const d of diags) {
        const fixes = ls.getCodeFixesAtPosition(f, d.start, d.start + d.length, [code], fmt, prefs)
        const withId = fixes.find((x) => x.fixId)
        if (withId) {
          fixId = withId.fixId
          break
        }
      }
      if (!fixId) continue
      const combined = ls.getCombinedCodeFix({ type: 'file', fileName: f }, fixId, fmt, prefs)
      if (combined.changes.length) {
        applyChanges(combined.changes)
        changedThisPass += diags.length
      }
    }
  }
  total += changedThisPass
  console.error(`pass ${pass}: ${changedThisPass}`)
  if (!changedThisPass) break
}
for (const [f, e] of files) if (e.dirty) fs.writeFileSync(f, e.text)
console.error('total', total)

