// Hoist @typedef/@callback blocks out of JSDoc comments attached to class members (and nested
// functions) into standalone JSDoc comments placed before the enclosing top-level statement.
const ts = require('/home/danny/Code/compx574/audiobookshelf/node_modules/typescript')
const fs = require('fs')

for (const file of process.argv.slice(2)) {
  let text = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const edits = []
  for (const top of sf.statements) {
    const hoisted = []
    const visit = (node) => {
      if (node !== top) {
        for (const doc of ts.getJSDocCommentsAndTags(node).filter(ts.isJSDoc)) {
          if (!doc.tags?.some((t) => ts.isJSDocTypedefTag(t) || ts.isJSDocCallbackTag(t))) continue
          const docText = doc.getText(sf)
          const lines = docText.split('\n')
          // split comment body lines into typedef section(s) vs the rest
          const keep = []
          const take = []
          let inTypedef = false
          for (let i = 0; i < lines.length; i++) {
            const raw = lines[i]
            const body = raw.replace(/^\s*\/?\*+\/?\s?/, '').replace(/\*\/\s*$/, '')
            const isFirst = i === 0
            const isLast = i === lines.length - 1
            if (isFirst || isLast) continue
            const tag = body.match(/^@(\w+)/)?.[1]
            if (tag === 'typedef' || tag === 'callback') inTypedef = true
            else if (tag && !['property', 'prop', 'param', 'returns', 'return', 'template'].includes(tag)) inTypedef = false
            else if (tag && ['param', 'returns', 'return'].includes(tag) && !take.length) inTypedef = false
            else if (tag && ['param', 'returns', 'return'].includes(tag) && inTypedef) {
              // @param/@returns after @typedef (not @callback) belong to the method
              const lastHead = [...take].reverse().find((l) => /@(typedef|callback)/.test(l))
              if (!/@callback/.test(lastHead || '')) inTypedef = false
            }
            ;(inTypedef ? take : keep).push(body)
          }
          if (!take.length) continue
          // drop trailing empty lines inside the hoisted block
          while (take.length && !take[take.length - 1].trim()) take.pop()
          while (keep.length && !keep[keep.length - 1].trim()) keep.pop()
          // split hoisted into one comment per typedef
          const blocks = []
          for (const l of take) {
