  let text = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const edits = []
  const visit = (node) => {
    if (ts.isFunctionLike(node) && node.type && node.modifiers?.some((m) => m.kind === ts.SyntaxKind.AsyncKeyword)) {
      const t = node.type
      const isPromise = ts.isTypeReferenceNode(t) && ts.isIdentifier(t.typeName) && t.typeName.text === 'Promise'
      if (!isPromise) {
        const inner = t.getText(sf)
        edits.push({ start: t.getStart(sf), end: t.getEnd(), text: `Promise<${inner === 'undefined' ? 'void' : inner}>` })
      }
    }
    if (ts.isGetAccessorDeclaration(node) && !node.type) {
      const tag = ts.getJSDocTags(node).find(ts.isJSDocTypeTag)
      if (tag) {
        const at = node.parameters.end + 1 // after ')'
        edits.push({ start: at, end: at, text: `: ${tag.typeExpression.type.getText(sf)}` })
      }
    }
    ts.forEachChild(node, visit)
  }
  visit(sf)
  if (!edits.length) continue
  edits.sort((a, b) => b.start - a.start)
  for (const e of edits) text = text.slice(0, e.start) + e.text + text.slice(e.end)
  fs.writeFileSync(file, text)
}

