// Model sweep: initModel rename, passthrough ctor removal, declare fields
const ts = require('/home/danny/Code/compx574/audiobookshelf/node_modules/typescript')
const fs = require('fs')

for (const file of process.argv.slice(2)) {
  let text = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const edits = []
  for (const stmt of sf.statements) {
    if (!ts.isClassDeclaration(stmt)) continue
    const ext = stmt.heritageClauses?.find((h) => h.token === ts.SyntaxKind.ExtendsKeyword)
    if (!ext || ext.types[0].expression.getText(sf) !== 'Model') continue
    for (const m of stmt.members) {
      if (ts.isConstructorDeclaration(m)) {
        const stmts = m.body.statements
        if (stmts.length === 1 && stmts[0].getText(sf).replace(/\s/g, '') === 'super(values,options)') {
          let start = m.getFullStart()
          let end = m.getEnd()
          edits.push({ start, end, text: '' })
        }
      } else if (ts.isMethodDeclaration(m) && m.name.getText(sf) === 'init' && m.modifiers?.some((x) => x.kind === ts.SyntaxKind.StaticKeyword)) {
        edits.push({ start: m.name.getStart(sf), end: m.name.getEnd(), text: 'initModel' })
        const p = m.parameters[0]
        if (p && p.type) edits.push({ start: p.type.getStart(sf), end: p.type.getEnd(), text: 'Sequelize' })
        else if (p) edits.push({ start: p.name.getEnd(), end: p.name.getEnd(), text: ': Sequelize' })
      } else if (ts.isPropertyDeclaration(m) && !m.initializer && !m.modifiers?.some((x) => [ts.SyntaxKind.DeclareKeyword, ts.SyntaxKind.StaticKeyword].includes(x.kind))) {
        edits.push({ start: m.name.getStart(sf), end: m.name.getStart(sf), text: 'declare ' })
      }
    }
  }
  if (!edits.length) continue
  edits.sort((a, b) => b.start - a.start)
  for (const e of edits) text = text.slice(0, e.start) + e.text + text.slice(e.end)
  // JSDoc param type of init
  text = text.replace(/@param \{import\('\.\.\/Database'\)\.sequelize\} sequelize/g, '@param sequelize')
  // ensure Sequelize type imported
  if (/: Sequelize\)/.test(text) && !/import \{[^}]*\bSequelize\b[^}]*\} from 'sequelize'/.test(text) && !/^import Sequelize = require\('sequelize'\)/m.test(text)) {
    text = text.replace(/import \{([^}]*)\} from 'sequelize'/, (all, names) => `import {${names.replace(/\s+$/, '')}, Sequelize } from 'sequelize'`)
  }
  fs.writeFileSync(file, text)
}

