// Export top-level types from an `export = ClassName` module via a merged namespace.
// usage: node nsexport.js <file> [TypeName ...]   (no names = all top-level type aliases/interfaces)
const ts = require('/home/danny/Code/compx574/audiobookshelf/node_modules/typescript')
const fs = require('fs')
const [file, ...names] = process.argv.slice(2)
let text = fs.readFileSync(file, 'utf8')
const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
const exp = sf.statements.find(ts.isExportAssignment)
if (!exp || !ts.isIdentifier(exp.expression)) throw new Error('no export = Identifier in ' + file)
const cls = exp.expression.text
const existingNs = sf.statements.find((s) => ts.isModuleDeclaration(s) && s.name.text === cls)
if (existingNs) throw new Error('namespace already exists in ' + file)
const decls = sf.statements.filter((s) => (ts.isTypeAliasDeclaration(s) || ts.isInterfaceDeclaration(s)) && !s.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword) && (!names.length || names.includes(s.name.text)))
if (!decls.length) {
  console.error('no types found', file)
  process.exit(0)
}
const edits = []
const nsBody = []
for (const d of decls) {
  const start = d.getFullStart()
  const full = text.slice(start, d.getEnd()).replace(/^\s*\n/, '')
  const body = full.replace(/^(\s*(?:\/\*\*[\s\S]*?\*\/\s*)?)(type|interface)\b/, '$1export $2')
  nsBody.push(
    body
      .split('\n')
      .map((l) => (l.trim() ? '  ' + l : l))
      .join('\n')
  )
  const tp = d.typeParameters ? `<${d.typeParameters.map((p) => p.getText(sf)).join(', ')}>` : ''
  const tpNames = d.typeParameters ? `<${d.typeParameters.map((p) => p.name.text).join(', ')}>` : ''
  edits.push({ start: d.getStart(sf) - (d.getStart(sf) - start) + (text.slice(start, d.getStart(sf)).match(/^\s*/)[0].length), end: d.getEnd(), text: `type ${d.name.text}${tp} = ${cls}.${d.name.text}${tpNames}` })
}
const nsText = `namespace ${cls} {\n${nsBody.join('\n\n')}\n}\n\n`
edits.push({ start: exp.getStart(sf), end: exp.getStart(sf), text: nsText })
edits.sort((a, b) => b.start - a.start)
for (const e of edits) text = text.slice(0, e.start) + e.text + text.slice(e.end)
fs.writeFileSync(file, text)
console.log('exported', decls.map((d) => d.name.text).join(', '), 'from', file)

