// Convert remaining JSDoc @typedef / @callback blocks into TS interfaces / type aliases.
const ts = require('/home/danny/Code/compx574/audiobookshelf/node_modules/typescript')
const fs = require('fs')

function jsdocTypeToTs(t) {
  return t
    .trim()
    .replace(/^\*$/, 'any')
    .replace(/\bObject\.<\s*([^,>]+)\s*,\s*([^>]+)>/g, 'Record<$1, $2>')
    .replace(/\bArray\.<([^>]+)>/g, '$1[]')
    .replace(/\bArray<([^>]+)>/g, '$1[]')
    .replace(/(^|[^.\w])Object\b(?!\.)/g, '$1any')
    .replace(/^\?(.+)$/, '$1 | null')
    .replace(/\bfunction\b/g, 'Function')
}

function indent(s, n = 2) {
  return s
    .split('\n')
    .map((l) => (l.trim() ? ' '.repeat(n) + l : l))
    .join('\n')
}

for (const file of process.argv.slice(2)) {
  let text = fs.readFileSync(file, 'utf8')
  if (!/@typedef|@callback/.test(text)) continue
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const edits = []
  const seen = new Set()
  for (const top of sf.statements) {
    const decls = []
    const visit = (node) => {
      for (const doc of ts.getJSDocCommentsAndTags(node).filter(ts.isJSDoc)) {
        if (seen.has(doc.pos)) continue
        seen.add(doc.pos)
        const tags = doc.tags || []
        const tdTags = tags.filter((t) => ts.isJSDocTypedefTag(t) || ts.isJSDocCallbackTag(t))
        if (!tdTags.length) continue
        // Parse comment lines manually: split into typedef blocks and remainder
        const lines = doc.getText(sf).split('\n').slice(1, -1).map((l) => l.replace(/^\s*\*\s?/, ''))
        const keep = []
        let cur = null
        const blocks = []
        for (const l of lines) {
          const m = l.match(/^@(\w+)\s*(.*)$/)
          if (m && (m[1] === 'typedef' || m[1] === 'callback')) {
            cur = { kind: m[1], head: m[2], props: [], params: [], returns: null, desc: [] }
            blocks.push(cur)
            continue
          }
          if (cur && m && (m[1] === 'property' || m[1] === 'prop')) {
            cur.props.push(m[2])
            continue
          }
          if (cur && cur.kind === 'callback' && m && m[1] === 'param') {
            cur.params.push(m[2])
            continue
          }
          if (cur && cur.kind === 'callback' && m && (m[1] === 'returns' || m[1] === 'return')) {
            cur.returns = m[2]
            continue
          }
          if (cur && !m && l.trim() && !blocks.length) continue
          if (m) cur = null
          if (cur && !l.trim()) continue
          if (cur) {
            cur.desc.push(l)
            continue
          }
          keep.push(l)
        }
        const parseTyped = (s) => {
          // "{T} name - desc" or "{T} [name] desc"
          let depth = 0
          let i = s.indexOf('{')
          let j = i
          for (; j < s.length; j++) {
            if (s[j] === '{') depth++
            else if (s[j] === '}') {
              depth--
              if (!depth) break
            }
          }
          const type = i >= 0 ? s.slice(i + 1, j) : '*'
          const rest = (i >= 0 ? s.slice(j + 1) : s).trim()
          const nm = rest.match(/^(\[[^\]]+\]|[\w$.]+)\s*(?:-\s*)?(.*)$/)
          let name = nm ? nm[1] : rest
          let optional = false
          if (name.startsWith('[')) {
            optional = true
            name = name.slice(1, -1).split('=')[0]
          }
          return { type: jsdocTypeToTs(type), name, optional, desc: nm ? nm[2] : '' }
        }
        for (const b of blocks) {
          let out
          const descDoc = b.desc.filter((l) => l.trim()).length ? `/**\n${b.desc.map((l) => ` * ${l}`.trimEnd()).join('\n')}\n */\n` : ''
          if (b.kind === 'callback') {
            const name = b.head.trim()
            const params = b.params.map(parseTyped).map((p) => `${p.name}${p.optional ? '?' : ''}: ${p.type}`)
            const ret = b.returns ? parseTyped(b.returns + ' x').type : 'void'
            out = `${descDoc}type ${name} = (${params.join(', ')}) => ${ret}`
          } else {
            const h = b.head.match(/^(?:\{(.+)\}\s+)?(\w+)\s*(.*)$/)
            const baseType = h[1] ? jsdocTypeToTs(h[1]) : null
            const name = h[2]
            const headDesc = h[3] ? `/** ${h[3].replace(/^-\s*/, '')} */\n` : ''
            if (b.props.length) {
              const props = b.props
                .map(parseTyped)
                .map((p) => `${p.desc ? `/** ${p.desc} */\n` : ''}${p.name}${p.optional ? '?' : ''}: ${p.type}`)
              const body = `{\n${indent(props.join('\n'))}\n}`
              out = baseType && !['any', 'object'].includes(baseType) ? `${headDesc}${descDoc}type ${name} = ${baseType} & ${body}` : `${headDesc}${descDoc}interface ${name} ${body}`
            } else {
              out = `${headDesc}${descDoc}type ${name} = ${baseType || 'any'}`
            }
          }
          decls.push(out)
        }
        while (keep.length && !keep[keep.length - 1].trim()) keep.pop()
        while (keep.length && !keep[0].trim()) keep.shift()
        const ind = text.slice(text.lastIndexOf('\n', doc.getStart(sf)) + 1, doc.getStart(sf))
        if (keep.length) edits.push({ start: doc.getStart(sf), end: doc.getEnd(), text: `/**\n${keep.map((l) => `${ind} * ${l}`.trimEnd()).join('\n')}\n${ind} */` })
        else {
          let end = doc.getEnd()
          while (text[end] === ' ' || text[end] === '\n') end++
          edits.push({ start: doc.getStart(sf), end, text: '' })
        }
      }
      ts.forEachChild(node, visit)
    }
    visit(top)
    if (decls.length) {
      const docs = ts.getJSDocCommentsAndTags(top).filter(ts.isJSDoc)
      const at = docs.length ? docs[0].getStart(sf) : top.getStart(sf)
      edits.push({ start: at, end: at, text: decls.join('\n\n') + '\n\n', insert: true })
    }
  }
  if (!edits.length) continue
  // inserts must come before removals at the same position
  edits.sort((a, b) => b.start - a.start || (a.insert ? 1 : 0) - (b.insert ? 1 : 0))
  for (const e of edits) text = text.slice(0, e.start) + e.text + text.slice(e.end)
  fs.writeFileSync(file, text)
  console.log('converted', file)
}

