 44	    this.host = settings.host
 45	    this.port = settings.port
 46	    this.secure = !!settings.secure
 47	    this.rejectUnauthorized = !!settings.rejectUnauthorized
 48	    this.user = settings.user
 49	    this.pass = settings.pass
 50	    this.testAddress = settings.testAddress
 51	    this.fromAddress = settings.fromAddress
 52	    this.ereaderDevices = settings.ereaderDevices?.map((d) => ({ ...d })) || []
 53	
