 61	    return {
 62	      id: this.id,
 63	      host: this.host,
 64	      port: this.port,
 65	      secure: this.secure,
 66	      rejectUnauthorized: this.rejectUnauthorized,
 67	      user: this.user,
 68	      pass: this.pass,
 69	      testAddress: this.testAddress,
 70	      fromAddress: this.fromAddress,
 71	      ereaderDevices: this.ereaderDevices.map((d) => ({ ...d }))
 72	    }
 73	  }
 74	
 75	  update(payload) {
 76	    if (!payload) return false
 77	
 78	    if (payload.port !== undefined) {
 79	      if (isNullOrNaN(payload.port)) payload.port = 465
 80	      else payload.port = Number(payload.port)
 81	    }
 82	    if (payload.secure !== undefined) payload.secure = !!payload.secure
 83	    if (payload.rejectUnauthorized !== undefined) payload.rejectUnauthorized = !!payload.rejectUnauthorized
 84	
 85	    if (payload.ereaderDevices !== undefined && !Array.isArray(payload.ereaderDevices)) payload.ereaderDevices = undefined
 86	
 87	    if (payload.ereaderDevices?.length) {
 88	      // Validate ereader devices
 89	      payload.ereaderDevices = payload.ereaderDevices
 90	        .map((device) => {
 91	          if (!device.name || !device.email) {
 92	            Logger.error(`[EmailSettings] Update ereader device is invalid`, device)
 93	            return null
 94	          }
 95	          if (!device.availabilityOption || !['adminOrUp', 'userOrUp', 'guestOrUp', 'specificUsers'].includes(device.availabilityOption)) {
 96	            device.availabilityOption = 'adminOrUp'
 97	          }
 98	          if (device.availabilityOption === 'specificUsers' && !device.users?.length) {
 99	            device.availabilityOption = 'adminOrUp'
100	          }
101	          if (device.availabilityOption !== 'specificUsers' && device.users?.length) {
102	            device.users = []
103	          }
104	          return device
105	        })
106	        .filter((d) => d)
107	    }
108	
109	    let hasUpdates = false
110	
111	    const json = this.toJSON()
112	    for (const key in json) {
113	      if (key === 'id') continue
114	
115	      if (payload[key] !== undefined && !areEquivalent(payload[key], json[key])) {
116	        this[key] = copyValue(payload[key])
117	        hasUpdates = true
118	      }
119	    }
120	
121	    return hasUpdates
122	  }
123	
124	  getTransportObject() {
125	    const payload = {
126	      host: this.host,
127	      secure: this.secure
128	    }
129	    // Only set to true for port 465 (https://nodemailer.com/smtp/#tls-options)
130	    if (this.port !== 465) {
131	      payload.secure = false
132	    }
133	    if (this.port) payload.port = this.port
134	    if (this.user && this.pass !== undefined) {
135	      payload.auth = {
136	        user: this.user,
137	        pass: this.pass
138	      }
139	    }
140	    // Allow self-signed certs (https://nodemailer.com/smtp/#3-allow-self-signed-certificates)
141	    if (!this.rejectUnauthorized) {
142	      payload.tls = {
143	        rejectUnauthorized: false
144	      }
145	    }
146	
147	    return payload
148	  }
149	
150	  /**
151	   *
152	   * @param {EreaderDeviceObject} device
153	   * @param {import('../../models/User')} user
154	   * @returns {boolean}
155	   */
156	  checkUserCanAccessDevice(device: EreaderDeviceObject, user: import('../../models/User')): boolean {
157	    let deviceAvailability = device.availabilityOption || 'adminOrUp'
158	    if (deviceAvailability === 'adminOrUp' && user.isAdminOrUp) return true
159	    if (deviceAvailability === 'userOrUp' && (user.isAdminOrUp || user.isUser)) return true
160	    if (deviceAvailability === 'guestOrUp') return true
161	    if (deviceAvailability === 'specificUsers') {
162	      let deviceUsers = device.users || []
163	      return deviceUsers.includes(user.id)
164	    }
165	    return false
166	  }
167	
168	  /**
169	   * Get ereader devices accessible to user
170	   *
171	   * @param {import('../../models/User')} user
172	   * @returns {EreaderDeviceObject[]}
173	   */
174	  getEReaderDevices(user: import('../../models/User')): EreaderDeviceObject[] {
175	    return this.ereaderDevices.filter((device) => this.checkUserCanAccessDevice(device, user))
176	  }
177	
178	  /**
179	   * Get ereader device by name
180	   *
181	   * @param {string} deviceName
182	   * @returns {EreaderDeviceObject}
183	   */
184	  getEReaderDevice(deviceName: string): EreaderDeviceObject {
185	    return this.ereaderDevices.find((d) => d.name === deviceName)
186	  }
187	}
