for (const file of process.argv.slice(2)) {
  let text = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const edits = []
  const visit = (n) => {
    if (ts.isPropertyAssignment(n) && n.name.getText(sf) === 'include' && ts.isObjectLiteralExpression(n.initializer)) {
      const parentObj = n.parent
      const hasModel = ts.isObjectLiteralExpression(parentObj) && parentObj.properties.some((p) => p.name && p.name.getText(sf) === 'model')
      if (hasModel) {
        edits.push({ pos: n.initializer.getStart(sf), text: '[' }, { pos: n.initializer.getEnd(), text: ']' })
      }
    }
    ts.forEachChild(n, visit)
  }
  visit(sf)
  if (!edits.length) continue
  total += edits.length / 2
  edits.sort((a, b) => b.pos - a.pos)
  for (const e of edits) text = text.slice(0, e.pos) + e.text + text.slice(e.pos)
  fs.writeFileSync(file, text)
  console.log(file, edits.length / 2)
}
console.log('total', total)
